{"lang":"java","code":"public class SwitchDemo {
    public static void main(String[] args) {
        int month = 8;

        // 基本的なアロー演算子の使用
        // 値を直接割り当て
        // すべてのcaseが処理されていないとコンパイルエラーが発生
        // break文が不要でfall-throughの危険がない
        String monthString = switch (month) {
            case 1 -> "January";
            case 2 -> "February";
            case 3 -> "March";
            case 4 -> "April";
            case 5 -> "May";
            case 6 -> "June";
            case 7 -> "July";
            case 8 -> "August";
            case 9 -> "September";
            case 10 -> "October";
            case 11 -> "November";
            case 12 -> "December";
            default -> "Invalid month";
        };

        // 方法2: 複数のcaseをまとめて処理
        String season = switch (month) {
            case 12, 1, 2 -> "Winter";
            case 3, 4, 5 -> "Spring";
            case 6, 7, 8 -> "Summer";
            case 9, 10, 11 -> "Fall";
            default -> "Invalid month";
        };

        System.out.println(monthString);
        System.out.println(season);
    }
}"}

