{"lang":"java","code":"public class PermutationExample {
    public void permute(List<Integer> nums, List<Integer> current, boolean[] used) {
        if (current.size() == nums.size()) {
            System.out.println(current); // 順列を1つ出力する例 
            return;
        }

        for (int i = 0; i < nums.size(); i++) {
            if (!used[i]) {
                used[i] = true;
                current.add(nums.get(i));

                permute(nums, current, used);

                // バックトラッキング（元に戻す処理）
                current.remove(current.size() - 1);
                used[i] = false;
            }
        }
    }

    public static void main(String[] args) {
        PermutationExample pe = new PermutationExample();
        List<Integer> nums = Arrays.asList(1, 2, 3);
        pe.permute(nums, new ArrayList<>(), new boolean[nums.size()]);
    }
}"}

{"lang":"java","code":"// アルゴリズム A: バブルソート - O(n²)
public class BubbleSort {
    public static void bubbleSort(int[] arr) {
        int n = arr.length;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n - i - 1; j++) {
                if (arr[j] > arr[j + 1]) {
                    // swap
                    int temp = arr[j];
                    arr[j] = arr[j + 1];
                    arr[j + 1] = temp;
                }
            }
        }
    }
}

// アルゴリズム B: マージソート - O(n log n)
public class MergeSort {
    public static void mergeSort(int[] arr) {
        if (arr.length <= 1) return;
        mergeSortRecursive(arr, 0, arr.length - 1);
    }

    private static void mergeSortRecursive(int[] arr, int left, int right) {
        if (left >= right) return;

        int mid = (left + right) / 2;
        mergeSortRecursive(arr, left, mid);
        mergeSortRecursive(arr, mid + 1, right);
        merge(arr, left, mid, right);
    }

    private static void merge(int[] arr, int left, int mid, int right) {
        int[] temp = new int[right - left + 1];
        int i = left, j = mid + 1, k = 0;

        while (i <= mid && j <= right) {
            if (arr[i] <= arr[j]) temp[k++] = arr[i++];
            else temp[k++] = arr[j++];
        }
        while (i <= mid) temp[k++] = arr[i++];
        while (j <= right) temp[k++] = arr[j++];

        System.arraycopy(temp, 0, arr, left, temp.length);
    }
}"}

