{"lang":"mermaid","code":"classDiagram
    direction BT

    %% Product（製品）
    class Product {
        <<interface>>
        +operation()
    }
    class ConcreteProduct {
        +operation()
    }

    %% Creator（作成者）
    class Creator {
        <<abstract>>
        +factoryMethod() : Product
        +anOperation()
    }
    class ConcreteCreator {
        +factoryMethod() : Product
    }

    %% 継承および実装関係
    ConcreteProduct ..|> Product : 実装
    ConcreteCreator --|> Creator : 継承

    %% 核心：具体的な作成者が具体的な製品を生成
    ConcreteCreator ..> ConcreteProduct : 生成

    %% ノート：ファクトリーメソッドの役割
    note for ConcreteCreator "factoryMethod()をオーバーライドして\nConcreteProductを返します""}

